self.visible_layers = {}
for _, tracks in self.group_order:
    for track in tracks:
        key = track.lower().replace(' ', '_')
        if 'action:' in key:
            key = 'actions'
        elif 'object:' in key:
            key = 'objects'
        elif 'event:' in key:
            key = 'events'
        elif 'search:' in key:
            key = 'visual_search'
        elif 'final highlights' in key.lower():
            key = 'highlights'
        self.visible_layers[key] = True
